(function(){
  CardSpoke_MODS.register('research-kit', {
    meta: {
      name: 'Research Kit',
      type: 'Kit',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Bundle of readability tweaks for research sprints',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onTypographyChange(ctx, isLarge){
      const size = isLarge ? '18px' : '16px';
      document.documentElement.style.setProperty('--body-size', size);
    },
    onDisable(){
      document.documentElement.style.removeProperty('--body-size');
    }
  });
})();
